import random
from sympy import primefactors

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(2, 5)
    integers = [rng.randint(2, 20) for _ in range(n)]
    N = 1
    for integer in integers:
        N *= integer

    answer = len(primefactors(N))

    check = sum(
        1
        for p in range(2, N + 1)
        if N % p == 0 and all(p % q != 0 for q in range(2, int(p**0.5) + 1))
    )

    assert answer == check, f"answer={answer} check={check}"

    problem = f"Let N = {integers[0]} * {integers[1]} * ... * {integers[-1]} be the product of {n} distinct positive integers. How many distinct prime divisors does N have? State only the integer."
    return problem, str(answer)


