import random

def generate(seed):
    rng = random.Random(seed)
    number = rng.randint(1, 20)

    # Intended route: Fibonacci sequence. The number of ways to express N as the sum of 1's and 2's is the (N+1)th Fibonacci number.
    # The Fibonacci sequence is defined as F(0) = 0, F(1) = 1, and F(n) = F(n-1) + F(n-2) for n > 1.
    def fibonacci(n):
        if n == 0:
            return 0
        elif n == 1:
            return 1
        else:
            a, b = 0, 1
            for _ in range(2, n + 1):
                a, b = b, a + b
            return b

    answer = fibonacci(number + 1)

    # Independent route: dynamic programming to count the number of ways to express N as the sum of 1's and 2's.
    # This route does not rely on the Fibonacci sequence and instead uses a bottom-up approach to count the number of ways.
    check = [0] * (number + 1)
    check[0] = 1
    for i in range(1, number + 1):
        check[i] = check[i - 1] + (check[i - 2] if i >= 2 else 0)

    assert answer == check[number], f"answer={answer} check={check[number]}"

    problem = (
        f"Let N = {number} be a positive integer. In how many ways can N be expressed as the sum of 1's and 2's? State only the integer."
    )

    return problem, str(answer)


